/* From Uiverse.io by LogariusIV - Tags: login, form */
.__UIV_SCOPE__ .form {
  display: flex;
  flex-direction: column;
  width: 280px;
  height: 350px;
  background-color: #FFF;
  margin: 0;
  box-shadow: -1px 0px 25px 0px #21719369;
  padding: 2.25em;
  box-sizing: border-box;
  border: solid 1px #DDD;
  border-radius: 0.5em;
  font-family: sans-serif;
  font-size: 16px;
  font-weight: 400;
}

.__UIV_SCOPE__ .form .Group {
  margin-bottom: 2em;
}

.__UIV_SCOPE__ .form label {
  margin: 0 0 10px;
  display: block;
  font-size: 1.25em;
  color: #217093;
  font-weight: 600;
  font-family: inherit;
}

.__UIV_SCOPE__ .form input {
  padding: 0.3em 0.5em 0.4em;
  background-color: #f3fafd;
  border: solid 2px #217093;
  border-radius: 4px;
  box-sizing: border-box;
  width: 100%;
  height: 50px;
  font-size: 1.3em;
  color: #353538;
  font-weight: 600;
  font-family: inherit;
  transition: box-shadow 0.2s linear, border-color 0.25s ease-out;
}

.__UIV_SCOPE__ .form input:focus {
  outline: none;
  box-shadow: 0px 2px 10px rgba(0, 0, 0, 0.1);
  background-color: #edf8fc;
  border: solid 2px #4eb8dd;
}

.__UIV_SCOPE__ .form input::placeholder {
  color: #21719383;
}

.__UIV_SCOPE__ .form .btn {
  margin: 0;
  padding: 0.5em;
  background-color: #4eb8dd;
  border: none;
  border-radius: 4px;
  box-sizing: border-box;
  box-shadow: none;
  width: 100%;
  height: 50px;
  font-size: 1.4em;
  color: #FFF;
  font-weight: 600;
  font-family: inherit;
  transition: transforme 0.1s ease-in-out, background-color 0.2s ease-out;
}

.__UIV_SCOPE__ .form .btn:hover {
  cursor: pointer;
  background-color: #217093;
}

.__UIV_SCOPE__ .form .btn:active {
  transform: scale(0.98);
}
